package ug.ac.mak.der.build;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.time.Instant;
import java.util.Properties;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.Resource;
import org.springframework.stereotype.Component;

/**
 * Reads build identity from {@code META-INF/build-info.properties} (generated by
 * Spring Boot's {@code build-info} goal) and {@code git.properties} (generated by
 * {@code git-commit-id-maven-plugin}) and exposes a single immutable
 * {@link BuildInfo} instance.
 *
 * <p>When the resources are absent — typical during ad-hoc {@code javac} compiles
 * in IDE scratch builds that skip Maven lifecycle plugins — the provider falls
 * back to the string {@code "unknown"} and the Unix epoch so that the health
 * endpoint still has a defined shape. The fallback is a Phase 00 deliberate
 * decision; later phases will tighten this.</p>
 */
@Component
public final class BuildInfoProvider {

    private static final String BUILD_INFO = "classpath:META-INF/build-info.properties";
    private static final String GIT_INFO = "classpath:git.properties";
    private static final String UNKNOWN = "unknown";

    private final BuildInfo buildInfo;

    public BuildInfoProvider(
            @Value(BUILD_INFO) final Resource buildInfoResource,
            @Value(GIT_INFO) final Resource gitInfoResource
    ) {
        final Properties buildProps = loadIfPresent(buildInfoResource);
        final Properties gitProps = loadIfPresent(gitInfoResource);

        final String release = buildProps.getProperty("build.der.release",
                buildProps.getProperty("build.version", UNKNOWN));
        final String dhis2 = buildProps.getProperty("build.dhis2.reference.version",
                BuildInfo.UNKNOWN_DHIS2_VERSION);
        final Instant buildTime = parseInstant(buildProps.getProperty("build.time"));
        final String commit = gitProps.getProperty("git.commit.id.abbrev",
                gitProps.getProperty("git.commit.id.full", UNKNOWN));
        final String branch = gitProps.getProperty("git.branch", UNKNOWN);
        final boolean dirty = Boolean.parseBoolean(gitProps.getProperty("git.dirty", "false"));

        this.buildInfo = new BuildInfo(release, commit, branch, dirty, buildTime, dhis2);
    }

    public BuildInfo buildInfo() {
        return buildInfo;
    }

    private static Properties loadIfPresent(final Resource resource) {
        final Properties props = new Properties();
        if (resource == null || !resource.exists()) {
            return props;
        }
        try (InputStream in = resource.getInputStream()) {
            props.load(in);
        } catch (IOException ex) {
            throw new UncheckedIOException("Failed to read " + resource.getDescription(), ex);
        }
        return props;
    }

    private static Instant parseInstant(final String raw) {
        if (raw == null || raw.isBlank()) {
            return Instant.EPOCH;
        }
        return Instant.parse(raw);
    }
}
